actions.action:
// No nexus - no filing required
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

            // Calculate IL state additions
            double additions = 0.0;

            // IL adds back interest on U.S. government obligations
            // (exempt from federal tax but taxable to IL)
            // additions += revenue.federal_bond_interest;

            // IL adds back IRC 199A deduction (state doesn't fully conform)
            // additions += result.section_199a_deduction;

            // IL may require depreciation adjustments for certain years
            // additions += result.il_depreciation_addback;

            apportionment.state_additions = additions;

            // Calculate IL state subtractions
            double subtractions = 0.0;

            // IL allows subtraction for interest on IL/local government bonds
            // subtractions += revenue.il_municipal_interest;

            // IL-specific deductions (e.g., domestic production activities)
            // subtractions += result.il_specific_deductions;

            apportionment.state_subtractions = subtractions;

            // IL uses flat 9.5% rate (35 ILCS 5/201(b) - highest in nation)
            apportionment.state_tax =
              apportionment.state_taxable_income * apportionment.state_tax_rate;

            // Subtract IL state credits
            apportionment.state_tax =
              Math.max(0.0, apportionment.state_tax - apportionment.state_credits);

            // Replacement tax will be added in table 50590
            // For now, calculate base refund/owed (will be adjusted by replacement tax)
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;

            // Replacement tax is 2.5% of net income (same base as income tax)
            result.il_replacement_tax =
              apportionment.state_taxable_income * result.il_replacement_tax_rate;

            // Add replacement tax to total state tax
            apportionment.state_tax = apportionment.state_tax + result.il_replacement_tax;

            // Recalculate refund or amount owed including replacement tax
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;
